import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Module 5 · Escrow","description":"","frontmatter":{},"headers":[],"relativePath":"modules/05-escrow.md","filePath":"modules/05-escrow.md","lastUpdated":1790431304000}'),n={name:"modules/05-escrow.md"};function o(r,e,l,d,h,c){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="module-5-·-escrow" tabindex="-1">Module 5 · Escrow <a class="header-anchor" href="#module-5-·-escrow" aria-label="Permalink to &quot;Module 5 · Escrow&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Contract</strong></td><td><code>TownEscrow.sol</code></td></tr><tr><td><strong>Stop</strong></td><td>Market</td></tr><tr><td><strong>Standard</strong></td><td>None — a state machine holding ERC-20</td></tr><tr><td><strong>Stamp</strong></td><td>Module 5 (awarded to the <strong>buyer</strong>)</td></tr></tbody></table><h2 id="the-problem" tabindex="-1">The problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The problem&quot;">​</a></h2><p>Two strangers want to trade. Whoever moves first carries all the risk: pay first and the goods may never arrive; ship first and the money may never come.</p><p>Every marketplace solves this the same way — a middleman holds the money. That works, and it costs a percentage, and it means the middleman can freeze your funds, go out of business, or decide your dispute by policy rather than fact.</p><h2 id="the-idea" tabindex="-1">The idea <a class="header-anchor" href="#the-idea" aria-label="Permalink to &quot;The idea&quot;">​</a></h2><p><strong>The contract moves first.</strong> The buyer pays into the contract, where neither party can touch it. The seller ships knowing the money exists. The buyer confirms and the seller is paid.</p><p>Then the two awkward cases, which are where the design actually lives:</p><ul><li>The buyer goes quiet. The seller can claim after a deadline.</li><li>Something is genuinely wrong. The buyer disputes, and an arbiter decides.</li></ul><h2 id="key-terms" tabindex="-1">Key terms <a class="header-anchor" href="#key-terms" aria-label="Permalink to &quot;Key terms&quot;">​</a></h2><p><strong>Escrow.</strong> Funds held by a third party until conditions are met. Here the third party is code.</p><p><strong>State machine.</strong> The order is always in exactly one of a few states, and only certain moves are allowed from each. Modelling this explicitly — rather than with a pile of booleans — is what makes the contract auditable.</p><p><strong>Deadline / timeout.</strong> A time after which someone gains a right they did not have. Without one, a silent counterparty freezes funds for ever, and &quot;for ever&quot; is literal.</p><p><strong>Arbiter.</strong> A role that can settle a dispute. It is a human, deliberately, and the interesting question is what they can and cannot do.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>None → Funded → Released      (buyer confirms)</span></span>
<span class="line"><span>             → Refunded       (arbiter sides with buyer)</span></span>
<span class="line"><span>             → Released       (seller claims after the deadline)</span></span>
<span class="line"><span>             → Disputed → Released / Refunded   (arbiter decides)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Function</th><th>Who</th><th>When</th></tr></thead><tbody><tr><td><code>createOrder(seller, amount, productId, window)</code></td><td>buyer</td><td>Pays in, sets the deadline</td></tr><tr><td><code>confirmReceipt(id)</code></td><td>buyer</td><td>Pays the seller</td></tr><tr><td><code>claimAfterWindow(id)</code></td><td>seller</td><td>Only after the deadline</td></tr><tr><td><code>dispute(id)</code></td><td>buyer</td><td>Only before the deadline</td></tr><tr><td><code>resolve(id, paySeller)</code></td><td><code>ARBITER_ROLE</code></td><td>Only from <code>Disputed</code></td></tr></tbody></table><p><code>window</code> is bounded: <code>MIN_WINDOW</code> one minute, <code>MAX_WINDOW</code> thirty days. Bounds rather than a constant, so the same contract suits a lab and a real sale — and so nobody sets a thousand-year window and traps the funds.</p><p><code>productId</code> optionally links the order to module 4, which is how the town&#39;s modules compose without depending on each other.</p><h2 id="the-detail-that-matters" tabindex="-1">The detail that matters <a class="header-anchor" href="#the-detail-that-matters" aria-label="Permalink to &quot;The detail that matters&quot;">​</a></h2><p><strong>What the arbiter can and cannot do:</strong></p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> resolve</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uint256</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bool</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> paySeller</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">external</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> onlyRole</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ARBITER_ROLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // ... pays either the seller or the buyer, in full</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>They choose <em>which of two parties</em> gets the money. They cannot:</p><ul><li>send it to a third address, including their own;</li><li>change the amount;</li><li>split it;</li><li>act on an order that is not disputed;</li><li>do anything at all once the order has settled.</li></ul><p>That is a deliberately narrow power, and the narrowness is the security property. Compare with a payment platform&#39;s dispute team, who can do all of those things and whose reasoning you never see.</p><p>It is also worth noticing what remains: the arbiter is a single trusted human. The contract removes the <em>custody</em> risk (nobody can run off with the money) while leaving a <em>judgement</em> risk. Most real systems do the same, and are less honest about it.</p><p><strong>The timeout protects the seller, not the buyer.</strong> A buyer who receives goods and never confirms is the common failure, and without <code>claimAfterWindow</code> the seller&#39;s money sits for ever. The dispute window is the buyer&#39;s counterbalance: dispute before the deadline and the automatic claim is blocked.</p><h2 id="walk-through-it" tabindex="-1">Walk through it <a class="header-anchor" href="#walk-through-it" aria-label="Permalink to &quot;Walk through it&quot;">​</a></h2><ol><li><strong>Buyer:</strong> create an order to a classmate.</li><li>Check the contract&#39;s TVD balance on the explorer. The money is in neither wallet.</li><li><strong>Seller:</strong> try to take it. There is no function that lets you.</li><li><strong>Buyer:</strong> confirm receipt. The seller is paid.</li></ol><p>Then the timeout path:</p><ol start="5"><li>Create a second order with a short window and do nothing.</li><li>After the deadline, the seller calls <code>claimAfterWindow</code>.</li></ol><p>Then the dispute path:</p><ol start="7"><li>Create a third order, dispute it before the deadline, and have the instructor resolve it.</li></ol><h2 id="what-actually-happened-on-chain" tabindex="-1">What actually happened on chain <a class="header-anchor" href="#what-actually-happened-on-chain" aria-label="Permalink to &quot;What actually happened on chain&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OrderCreated(id: 3, buyer: 0x…, seller: 0x…, amount: 25e18, deadline: 1790…)</span></span>
<span class="line"><span>Transfer(from: buyer, to: escrow, value: 25e18)     // the ERC-20 moving in</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>Released(id: 3, to: seller, amount: 25e18)</span></span>
<span class="line"><span>Transfer(from: escrow, to: seller, value: 25e18)</span></span>
<span class="line"><span>Stamped(tokenId: …, moduleId: 5, by: escrow)</span></span></code></pre></div><p>Note the buyer needed <strong>two</strong> transactions to create the order: <code>approve</code> on the token, then <code>createOrder</code>. Users find this surprising every time; it exists so that a contract can only take what you explicitly allowed.</p><h2 id="when-a-plain-database-is-better" tabindex="-1">When a plain database is better <a class="header-anchor" href="#when-a-plain-database-is-better" aria-label="Permalink to &quot;When a plain database is better&quot;">​</a></h2><p>eBay and Stripe do this at enormous scale, with fraud detection, chargebacks and a phone number to call. For most commerce they are simply better.</p><p>Escrow on a chain matters when: the parties are in different jurisdictions with no shared platform; the platform itself is the risk; or the goods are on chain, in which case the whole trade can settle atomically and escrow disappears into a swap.</p><p>Be honest about the cost side too. This escrow has no fraud detection, no identity, no chargeback, and a dispute process consisting of one person with a role.</p><h2 id="what-this-does-not-fix" tabindex="-1">What this does not fix <a class="header-anchor" href="#what-this-does-not-fix" aria-label="Permalink to &quot;What this does not fix&quot;">​</a></h2><ul><li><strong>It does not know if the goods arrived.</strong> <code>confirmReceipt</code> is the buyer saying so.</li><li><strong>The arbiter is a single point of trust.</strong> They cannot steal, but they can be wrong, biased, or unavailable.</li><li><strong>A buyer who disputes everything</strong> costs the seller time; nothing here penalises that.</li><li><strong>Goods that are fine but not as described</strong> are exactly the case where code has no opinion.</li></ul><h2 id="common-mistakes" tabindex="-1">Common mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common mistakes&quot;">​</a></h2><ul><li><strong>No timeout.</strong> Funds locked for ever by a silent party. The single most common escrow bug.</li><li><strong>Letting the arbiter choose the recipient.</strong> Instant rug. Restrict to the two parties.</li><li><strong>Sending before updating state.</strong> Set the state first, then transfer — checks, effects, interactions.</li><li><strong>Forgetting <code>approve</code>.</strong> The order creation reverts with an allowance error that means nothing to a user unless you decode it.</li><li><strong>Assuming ERC-20 transfers return true.</strong> Some tokens do not. <code>SafeERC20</code> handles it, which is why the contract uses it.</li></ul><h2 id="security-checklist" tabindex="-1">Security checklist <a class="header-anchor" href="#security-checklist" aria-label="Permalink to &quot;Security checklist&quot;">​</a></h2><ul><li>[ ] Can the arbiter send funds anywhere other than the two parties?</li><li>[ ] Can the seller claim before the deadline? Can the buyer dispute after it?</li><li>[ ] Can an order be released twice?</li><li>[ ] What happens if the buyer disputes and the arbiter never responds?</li><li>[ ] Is the window bounded at both ends?</li><li>[ ] Could a malicious token contract reenter during a transfer?</li></ul><h2 id="extend-it" tabindex="-1">Extend it <a class="header-anchor" href="#extend-it" aria-label="Permalink to &quot;Extend it&quot;">​</a></h2><ol><li>Replace the single arbiter with the module 11 multisig, then with the module 12 DAO. Time each. Which would you accept as a seller?</li><li>Add partial refunds — the arbiter splits the amount. What new abuse does that enable, and what would you add to contain it?</li><li>Add a seller bond, forfeited on a lost dispute, so disputes cost the wrong party something. Then work out how a buyer could exploit that.</li></ol><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="https://docs.openzeppelin.com/contracts/5.x/api/token/erc20#SafeERC20" target="_blank" rel="noreferrer">OpenZeppelin SafeERC20</a></li><li><a href="https://docs.soliditylang.org/en/latest/security-considerations.html#use-the-checks-effects-interactions-pattern" target="_blank" rel="noreferrer">Checks-Effects-Interactions</a></li></ul><p><strong>Next:</strong> <a href="./06-sealed-bid-auction">Module 6 · Sealed-bid auction →</a></p>`,51)])])}const m=t(n,[["render",o]]);export{u as __pageData,m as default};
